function test_capitalize() {
    $exchange = new \ccxt\async\Exchange(array(
        'id' => 'sampleexchange',
    ));
    // `inputs` and `expected` must stay index-aligned; every row is asserted below
    $inputs = ['hello', 'fooBar', 'helloWorld', 'Hello', 'hELLO', 'a', 'A', '', '123abc', 'hello world', 'foo_bar_baz', 'aBC'];
    $expected = ['Hello', 'FooBar', 'HelloWorld', 'Hello', 'HELLO', 'A', 'A', '', '123abc', 'Hello world', 'Foo_bar_baz', 'ABC'];
    for ($i = 0; $i < count($inputs); $i++) {
        assert($exchange->capitalize($inputs[$i]) === $expected[$i], 'capitalize(' . $inputs[$i] . ') must equal ' . $expected[$i]);
    }
}
